#pragma once
#include <string.h>

// Returns 1 if s contains a balanced mix of (), [], {} - matched by TYPE and
// properly nested - and 0 otherwise. Non-bracket characters are ignored.
static int is_balanced(const char *s) {
    char stack[256];
    int top = 0;
    size_t n = strlen(s);

    for (size_t i = 0; i < n; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            if (top >= (int)(sizeof(stack) / sizeof(stack[0]))) {
                return 0; // too deeply nested for this fixed-size stack
            }
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) {
                return 0; // closer with nothing open
            }
            char open = stack[top - 1];
            int matches = (c == ')' && open == '(') ||
                          (c == ']' && open == '[') ||
                          (c == '}' && open == '{');
            if (!matches) {
                return 0; // wrong type of closer
            }
            top--;
        }
    }
    return top == 0;
}

reference_solution.test_is_balanced.c:
#include "is_balanced.h"
#include <assert.h>
#include <stdio.h>

int main(void) {
    assert(is_balanced("()") == 1);
    assert(is_balanced("([{}])") == 1);
    assert(is_balanced("a(b)c[d]e") == 1);
    assert(is_balanced("") == 1);

    assert(is_balanced("(") == 0);
    assert(is_balanced(")") == 0);
    assert(is_balanced("(]") == 0);
    assert(is_balanced("([)]") == 0);
    assert(is_balanced("(((") == 0);

    printf("PASS\n");
    return 0;
}

